<div class="form-grid"><div class="field field-wide"><label for="task_name">Task name <span>*</span></label><input id="task_name" name="task_name" type="text" value="{{ old('task_name', $task->task_name ?? '') }}" placeholder="What needs to be done?" required maxlength="120"></div><div class="field"><label for="due_date">Due date</label><input id="due_date" name="due_date" type="date" value="{{ old('due_date', isset($task) && $task->due_date ? $task->due_date->format('Y-m-d') : '') }}"></div><div class="field"><label for="status">Status</label><select id="status" name="status"><option value="Pending" @selected(old('status', $task->status ?? 'Pending') === 'Pending')>Pending</option><option value="Completed" @selected(old('status', $task->status ?? '') === 'Completed')>Completed</option></select></div><div class="field field-wide"><label for="description">Description <small>Optional</small></label><textarea id="description" name="description" rows="5" placeholder="Add a little context...">{{ old('description', $task->description ?? '') }}</textarea></div></div>